import{_ as e,a as s}from"./chunks/edit_pack.BgW_0E6q.js";import{_ as i,c as n,o as t,ae as o}from"./chunks/framework.BrQRMotl.js";const m=JSON.parse('{"title":"Sound Pack Manager","description":"","frontmatter":{},"headers":[],"relativePath":"manual/sound_packs.md","filePath":"manual/sound_packs.md"}'),r={name:"manual/sound_packs.md"};function l(c,a,d,p,h,u){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="sound-pack-manager" tabindex="-1">Sound Pack Manager <a class="header-anchor" href="#sound-pack-manager" aria-label="Permalink to &quot;Sound Pack Manager&quot;">​</a></h1><p>Extended Note Block Sound Packs are essentially standard <strong>Minecraft Resource Packs</strong>, making them easy to share and install. The mod provides a built-in manager to simplify the creation and switching process.</p><h2 id="opening-the-manager" tabindex="-1">Opening the Manager <a class="header-anchor" href="#opening-the-manager" aria-label="Permalink to &quot;Opening the Manager&quot;">​</a></h2><ul><li>In the game settings page, find and open <code>Sound Packs...</code>.</li></ul><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><h3 id="_1-browse-activate" tabindex="-1">1. Browse &amp; Activate <a class="header-anchor" href="#_1-browse-activate" aria-label="Permalink to &quot;1. Browse &amp; Activate&quot;">​</a></h3><p><img src="'+e+'" alt="SoundPackManager"></p><ul><li>The manager lists all recognized Extended Note Block sound packs in the <code>resourcepacks</code> directory.</li><li>Selecting a sound pack activates it. This effectively places the resource pack at the top of Minecraft&#39;s resource pack list enabled.</li></ul><h3 id="_2-create-new-sound-pack" tabindex="-1">2. Create New Sound Pack <a class="header-anchor" href="#_2-create-new-sound-pack" aria-label="Permalink to &quot;2. Create New Sound Pack&quot;">​</a></h3><ul><li>Click the &quot;New&quot; button, enter a name, and the mod will automatically create a new folder structure under <code>.minecraft/resourcepacks/</code>.</li><li>Automatically generated files include <code>pack.mcmeta</code> (Resource Pack Metadata) and <code>pack.json</code> (Sound Pack Configuration).</li></ul><h3 id="_3-edit-refresh" tabindex="-1">3. Edit &amp; Refresh <a class="header-anchor" href="#_3-edit-refresh" aria-label="Permalink to &quot;3. Edit &amp; Refresh&quot;">​</a></h3><p><img src="'+s+`" alt="EditPack"></p><ul><li>You can open the sound pack directly as a normal folder for editing.</li><li>After modifying files, click <strong>&quot;Refresh&quot;</strong> in-game, and the mod will rescan the directory, update <code>sounds.json</code>, and reload resources without restarting the game.</li></ul><h2 id="sound-pack-creation-guide" tabindex="-1">Sound Pack Creation Guide <a class="header-anchor" href="#sound-pack-creation-guide" aria-label="Permalink to &quot;Sound Pack Creation Guide&quot;">​</a></h2><p>If you want to manually create or modify a sound pack, please follow these specifications:</p><h3 id="directory-location" tabindex="-1">Directory Location <a class="header-anchor" href="#directory-location" aria-label="Permalink to &quot;Directory Location&quot;">​</a></h3><p>All sound packs are located in the standard resource pack directory: <code>.minecraft/resourcepacks/</code></p><h3 id="file-structure" tabindex="-1">File Structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File Structure&quot;">​</a></h3><p>A standard sound pack structure is as follows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MySoundPack/</span></span>
<span class="line"><span>├── pack.mcmeta          # (Required) Standard Minecraft Resource Pack Metadata</span></span>
<span class="line"><span>├── pack.json            # (Required) Extended Note Block specific configuration</span></span>
<span class="line"><span>└── assets</span></span>
<span class="line"><span>    └── extendednoteblock</span></span>
<span class="line"><span>        ├── sounds.json  # (Auto-generated) Defines sound events, usually maintained automatically by the mod</span></span>
<span class="line"><span>        └── sounds</span></span>
<span class="line"><span>            └── notes    # (Core) Place audio files here</span></span></code></pre></div><h3 id="audio-file-specifications" tabindex="-1">Audio File Specifications <a class="header-anchor" href="#audio-file-specifications" aria-label="Permalink to &quot;Audio File Specifications&quot;">​</a></h3><ol><li><strong>Format</strong>: Must be in <strong><code>.ogg</code></strong> format (Vorbis encoding). <code>.wav</code> or <code>.mp3</code> are not supported.</li><li><strong>Naming</strong>: Filenames must follow the <code>InstrumentID.NoteID.ogg</code> format. <ul><li><strong>InstrumentID</strong>: Corresponds to the instrument number in the mod (e.g., 0 is Harp/Piano).</li><li><strong>NoteID</strong>: MIDI pitch number (0-127).</li><li>Example: <code>0.60.ogg</code> represents Instrument 0 (Piano), Middle C.</li></ul></li></ol><h3 id="configuration-file-pack-json" tabindex="-1">Configuration File (pack.json) <a class="header-anchor" href="#configuration-file-pack-json" aria-label="Permalink to &quot;Configuration File (pack.json)&quot;">​</a></h3><p>This is the key file for the mod to recognize the sound pack.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;displayName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My Sound Pack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available_instruments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">54</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">66</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">72</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// List of sampled pitches available for Instrument 0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><em>Note: Usually you only need to place the audio files and click &quot;Refresh&quot;, the mod will automatically update this file.</em></p><h2 id="why-use-sound-packs" tabindex="-1">Why Use Sound Packs? <a class="header-anchor" href="#why-use-sound-packs" aria-label="Permalink to &quot;Why Use Sound Packs?&quot;">​</a></h2><ul><li><strong>Infinite Expansion</strong>: As long as you place samples according to the naming rules, you can play the sound of any real instrument in the game.</li><li><strong>Smart Mapping</strong>: You don&#39;t need to record samples for every pitch. The mod automatically maps unrecorded notes to the nearest available sample and adjusts the pitch for playback.</li><li><strong>High Compatibility</strong>: Since they are standard resource packs, you can distribute your sound packs just like ordinary texture packs.</li></ul>`,28)])])}const f=i(r,[["render",l]]);export{m as __pageData,f as default};
